import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack?: () => void;
  variant?: 'full' | 'compact'; // 'full' = celá stránka, 'compact' = widget do menu
  currentUserId?: string;
}

type SortType = 'SCORE' | 'GRIND' | 'STREAK';

export const Leaderboard: React.FC<Props> = ({ subject, onBack, variant = 'full', currentUserId }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ uid: doc.id, displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ uid: doc.id, displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error instanceof Error ? error.message : error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    if (sortType === 'SCORE') {
      // Primárně podle nejlepšího skóre
      if (statsB.bestScorePercent !== statsA.bestScorePercent) {
        return statsB.bestScorePercent - statsA.bestScorePercent;
      }
      return (statsB.bestStreak || 0) - (statsA.bestStreak || 0);
    } else if (sortType === 'GRIND') {
      // Primárně podle počtu testů
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      return statsB.bestScorePercent - statsA.bestScorePercent;
    } else {
      // Primárně podle streaku
      const streakA = statsA.bestStreak || 0;
      const streakB = statsB.bestStreak || 0;
      if (streakB !== streakA) return streakB - streakA;
      return statsB.bestScorePercent - statsA.bestScorePercent;
    }
  });

  // Logika pro zobrazení
  let displayUsers = sortedUsers;
  let currentUserRankIndex = -1;

  if (currentUserId) {
      currentUserRankIndex = sortedUsers.findIndex(u => u.uid === currentUserId);
  }

  // V kompaktním režimu ukážeme jen TOP 5, ale pokud je uživatel níže, přidáme ho nakonec
  if (variant === 'compact') {
      displayUsers = sortedUsers.slice(0, 5);

      // Pokud je uživatel v seznamu, ale není v TOP 5, přidáme ho
      if (currentUserRankIndex > 4) {
          // Přidáme "..." (reprezentováno null) a pak uživatele
          // Použijeme typ any v poli pro zjednodušení renderování oddělovače
          displayUsers = [...displayUsers, null as any, sortedUsers[currentUserRankIndex]];
      }
  }

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300";
    if (index === 1) return "bg-gray-100 text-gray-700 border-gray-300";
    if (index === 2) return "bg-orange-100 text-orange-800 border-orange-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  // Helper funkce pro výpočet průměru
  const calculateAverage = (totalPoints: number, totalMaxPoints: number) => {
      if (!totalMaxPoints || totalMaxPoints === 0) return 0;
      return Math.round((totalPoints / totalMaxPoints) * 100);
  };

  return (
    <div className={`${variant === 'full' ? 'max-w-6xl mx-auto p-4 min-h-screen' : 'w-full h-full flex flex-col'}`}>

      {/* Header */}
      <div className={`flex items-center justify-between ${variant === 'full' ? 'mb-8' : 'mb-4'}`}>
        {variant === 'full' && onBack && (
            <button 
                onClick={onBack}
                className="flex items-center text-gray-500 hover:text-gray-900 transition-colors"
            >
                <svg className="w-6 h-6 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Zpět
            </button>
        )}
        <h1 className={`font-bold ${variant === 'full' ? 'text-2xl' : 'text-lg'} ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            {variant === 'full' ? `Žebříček ${subject}` : `Top ${subject}`}
        </h1>
      </div>

      {/* Přepínač řazení pouze pro plnou verzi */}
      {variant === 'full' && (
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
            <div className="text-gray-500 text-sm">
                Řadit podle:
            </div>
            <div className="flex flex-wrap gap-2 bg-gray-100 p-1 rounded-lg">
                <button 
                    onClick={() => setSortType('SCORE')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'SCORE' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🎯</span> Nejlepší výkon
                </button>
                <button 
                    onClick={() => setSortType('GRIND')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'GRIND' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>💪</span> Počet testů
                </button>
                <button 
                    onClick={() => setSortType('STREAK')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'STREAK' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🔥</span> Streak
                </button>
            </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Načítám data...</div>
      ) : sortedUsers.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl shadow-sm border border-gray-200 border-dashed">
            <p className="text-gray-400 text-sm">Zatím žádné statistiky.</p>
        </div>
      ) : (
        <div className={`bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex-1 ${variant === 'compact' ? 'text-sm' : ''}`}>
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-xs uppercase tracking-wider border-b border-gray-200">
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center w-8`}>#</th>
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'}`}>Jméno</th>

                            {/* Sloupce - Plná verze (více místa) */}
                            {variant === 'full' && (
                                <>
                                    <th className="px-6 py-4 text-center whitespace-nowrap" title="Počet dokončených testů">Počet testů</th>
                                    <th className="px-6 py-4 text-center whitespace-nowrap" title="Průměr ze všech testů">Průměr</th>
                                    <th className="px-6 py-4 text-center whitespace-nowrap" title="Nejlepší výsledek testu">Nejlepší</th>
                                    <th className="px-6 py-4 text-center text-red-600 whitespace-nowrap" title="Největší skóre v náhlé smrti">Sudden Death 🔥</th>
                                </>
                            )}

                            {/* Sloupce - Kompaktní verze */}
                            {variant === 'compact' && (
                                <>
                                    <th className="px-1 py-2 text-center text-[10px] w-8" title="Počet testů">Testy</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8" title="Průměr">Ø</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-10" title="Nejlepší">Max</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8 text-red-600" title="Streak">🔥</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {displayUsers.map((user, i) => {
                            // Render oddělovače (pokud je user null)
                            if (!user) {
                                return (
                                    <tr key="separator" className="bg-gray-50">
                                        <td colSpan={variant === 'compact' ? 6 : 6} className="text-center py-1 text-gray-400 text-xs">
                                            • • •
                                        </td>
                                    </tr>
                                );
                            }

                            // Musíme najít skutečný rank v sortedUsers poli
                            const realRank = sortedUsers.findIndex(u => u.uid === user.uid);
                            const isMe = user.uid === currentUserId;

                            const stats = getStats(user)!;
                            const avgPercent = calculateAverage(stats.totalPoints, stats.totalMaxPoints);
                            const bestStreak = stats.bestStreak || 0;

                            return (
                                <tr key={user.uid} className={`transition-colors ${isMe ? 'bg-blue-50/80 border-l-4 border-l-blue-500' : 'hover:bg-gray-50'}`}>
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center`}>
                                        <div className={`${variant === 'compact' ? 'w-6 h-6 text-xs' : 'w-8 h-8'} rounded-full flex items-center justify-center mx-auto font-bold border ${getMedalColor(realRank)}`}>
                                            {realRank + 1}
                                        </div>
                                    </td>
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} font-medium text-gray-900 truncate max-w-[100px] sm:max-w-none`}>
                                        {user.displayName} {isMe && <span className="text-[10px] text-blue-600 ml-1">(Ty)</span>}
                                    </td>

                                    {/* Plná verze tabulky */}
                                    {variant === 'full' && (
                                        <>
                                            <td className="px-6 py-4 text-center text-gray-600 font-medium">
                                                {stats.testsTaken}x
                                            </td>
                                            <td className="px-6 py-4 text-center font-medium text-blue-600">
                                                {avgPercent}%
                                            </td>
                                            <td className="px-6 py-4 text-center font-bold text-gray-800 text-lg">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-6 py-4 text-center font-black text-red-600 text-lg">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}

                                    {/* Kompaktní verze widgetu */}
                                    {variant === 'compact' && (
                                        <>
                                            <td className="px-1 py-2 text-center text-xs text-gray-500">
                                                {stats.testsTaken}
                                            </td>
                                            <td className="px-1 py-2 text-center text-xs font-medium text-blue-600">
                                                {avgPercent}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-bold text-gray-800">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-black text-red-600">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            {variant === 'compact' && sortedUsers.length > 5 && currentUserRankIndex <= 4 && (
                <div 
                    onClick={onBack} 
                    className="bg-gray-50 p-2 text-center text-xs text-gray-500 hover:text-blue-600 hover:bg-gray-100 cursor-pointer border-t border-gray-100 transition-colors"
                >
                    Zobrazit všech {sortedUsers.length} studentů...
                </div>
            )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { QUESTIONS_SPS, QUESTIONS_STT } from './constants';
import { AppMode, TestResult, Question, Subject } from './types';
import { TestRunner } from './components/TestRunner';
import { BrowserQuestionItem } from './components/BrowserQuestionItem';
import { LoginScreen } from './components/LoginScreen';
import { Leaderboard } from './components/Leaderboard';
import { SPSInfoModal } from './components/SPSInfoModal';
import { STTInfoModal } from './components/STTInfoModal';
import { ReportModal } from './components/ReportModal';
import { BattleManager } from './components/BattleManager';
import { SuddenDeathGame } from './components/SuddenDeathGame';
import { AppUser } from './users';
import { db, auth } from './firebaseConfig';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AppUser | null>(null);
  const [loadingUser, setLoadingUser] = useState(true);

  const [subject, setSubject] = useState<Subject | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.MENU);

  const [showSPSPopup, setShowSPSPopup] = useState(false);
  const [showSTTPopup, setShowSTTPopup] = useState(false);
  const [reportingQuestionId, setReportingQuestionId] = useState<number | null>(null);

  const [mistakesSPS, setMistakesSPS] = useState<number[]>([]);
  const [mistakesSTT, setMistakesSTT] = useState<number[]>([]);
  const [statsSPS, setStatsSPS] = useState<any>(null);

  const [lastResult, setLastResult] = useState<TestResult | null>(null);
  const [browserSearch, setBrowserSearch] = useState("");
  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());
  const [lastTestQuestions, setLastTestQuestions] = useState<Question[]>([]);
  const [lastUserAnswers, setLastUserAnswers] = useState<Record<number, number>>({});

  useEffect(() => {
      if(!auth) {
          setLoadingUser(false);
          return;
      }
      const unsubscribe = onAuthStateChanged(auth, (user) => {
          if (user) {
              setCurrentUser({
                  uid: user.uid,
                  email: user.email || '',
                  displayName: user.displayName || 'Student'
              });
          } else {
              setCurrentUser(null);
          }
          setLoadingUser(false);
      });
      return () => unsubscribe();
  }, []);

  const handleLogout = () => {
      localStorage.removeItem('app_session_id');
      if(auth) signOut(auth);
      setSubject(null);
      setMode(AppMode.MENU);
      setLastResult(null);
  };

  useEffect(() => {
    if (currentUser && db) {
        const userDocRef = doc(db, "users", currentUser.uid);

        // OPRAVA: Uložíme jméno uživatele do databáze, aby bylo vidět v žebříčku
        setDoc(userDocRef, { 
            displayName: currentUser.displayName,
            email: currentUser.email 
        }, { merge: true }).catch(err => console.error("Chyba při ukládání jména:", err));

        const unsubDoc = onSnapshot(userDocRef, (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                setMistakesSPS(data.mistakesSPS || []);
                setMistakesSTT(data.mistakesSTT || []);
                setStatsSPS(data.statsSPS || null);
            }
        });
        return () => unsubDoc();
    }
  }, [currentUser]);

  const currentQuestions = useMemo(() => {
    if (subject === 'SPS') return QUESTIONS_SPS;
    if (subject === 'STT') return QUESTIONS_STT;
    return [];
  }, [subject]);

  const filteredBrowserQuestions = useMemo(() => {
    if (mode !== AppMode.BROWSER) return [];
    const search = browserSearch.toLowerCase().trim();
    if (!search) return currentQuestions;
    return currentQuestions.filter(q => 
        q.id.toString() === search || 
        q.text.toLowerCase().includes(search)
    );
  }, [mode, currentQuestions, browserSearch]);

  const currentMistakes = subject === 'SPS' ? mistakesSPS : mistakesSTT;

  const setMistakes = async (newMistakes: number[]) => {
      if (subject === 'SPS') setMistakesSPS(newMistakes);
      else if (subject === 'STT') setMistakesSTT(newMistakes);
      if (currentUser && db) {
          const userDocRef = doc(db, "users", currentUser.uid);
          const updateData = subject === 'SPS' ? { mistakesSPS: newMistakes } : { mistakesSTT: newMistakes };
          await setDoc(userDocRef, updateData, { merge: true });
      }
  };

  const handleSPSSelection = () => {
    const isHidden = localStorage.getItem('hideSPSInfo');
    if (isHidden) { setSubject('SPS'); setBrowserSearch(""); } 
    else { setShowSPSPopup(true); }
  };

  const handleSTTSelection = () => {
    const isHidden = localStorage.getItem('hideSTTInfo');
    if (isHidden) { setSubject('STT'); setBrowserSearch(""); } 
    else { setShowSTTPopup(true); }
  };

  const handleTestComplete = (result: TestResult) => {
    setLastResult(result);
    if (mode === AppMode.MOCK_TEST) {
        setMistakes(Array.from(new Set([...currentMistakes, ...result.mistakes])));
        setLastTestQuestions(result.questionsUsed);
        setLastUserAnswers(result.userAnswers);
    } else if (mode === AppMode.MISTAKES) {
        setMistakes(result.mistakes);
    }
    setMode(AppMode.MENU);
  };

  const toggleExpand = (id: number) => {
    setExpandedIds(prev => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
    });
  };

  const expandAllVisible = () => {
    const allIds = filteredBrowserQuestions.map(q => q.id);
    setExpandedIds(new Set(allIds));
  };

  const collapseAll = () => {
    setExpandedIds(new Set());
  };

  const getMenuButtonClass = (color: string) => 
    `w-full p-6 rounded-xl shadow-md transition-all duration-300 transform hover:-translate-y-1 hover:shadow-xl flex flex-col items-center justify-center gap-3 text-center border border-gray-100 ${color}`;

  if (loadingUser) return <div className="min-h-screen flex items-center justify-center text-gray-500">Načítám...</div>;
  if (!currentUser) return <LoginScreen onLogin={(user) => setCurrentUser(user)} />;

  return (
    <div className="min-h-screen bg-slate-50 text-gray-900 font-sans relative">
      <div className="fixed bottom-2 right-4 text-[10px] text-gray-300 pointer-events-none z-[100] select-none">
          User: {currentUser.displayName}
      </div>

      {reportingQuestionId !== null && subject && (
        <ReportModal questionId={reportingQuestionId} subject={subject} userName={currentUser.displayName} onClose={() => setReportingQuestionId(null)} />
      )}

      {showSPSPopup && (
        <SPSInfoModal onConfirm={() => { setShowSPSPopup(false); setSubject('SPS'); setBrowserSearch(""); }} />
      )}

      {showSTTPopup && (
        <STTInfoModal onConfirm={() => { setShowSTTPopup(false); setSubject('STT'); setBrowserSearch(""); }} />
      )}

      {lastResult && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl animate-in fade-in zoom-in duration-300">
                <div className="text-center">
                    <div className={`mx-auto w-20 h-20 rounded-full flex items-center justify-center mb-4 ${lastResult.passed ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {lastResult.passed ? <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg> : <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>}
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-1">{lastResult.passed ? "Prošel(a) jsi!" : "Neprošel(a) jsi"}</h2>
                    <p className="text-gray-500 mb-6">Skóre: <span className="font-bold text-gray-800">{Math.round((lastResult.score / lastResult.total) * 100)}%</span> ({lastResult.score}/{lastResult.total})</p>
                    <button onClick={() => setLastResult(null)} className="w-full py-3 rounded-lg bg-gray-900 text-white font-bold hover:bg-gray-800 transition-colors">Zavřít</button>
                </div>
            </div>
        </div>
      )}

      {!subject && (
      <div className="max-w-7xl mx-auto min-h-screen flex flex-col p-6">
          <div className="flex justify-end items-center gap-4 mb-12">
              <span className="text-gray-600 font-medium bg-white px-4 py-2 rounded-full shadow-sm border border-gray-100">👤 {currentUser.displayName}</span>
              <button onClick={handleLogout} className="text-sm text-red-500 hover:text-red-700 font-semibold border border-red-200 px-4 py-2 rounded-full hover:bg-red-50 transition-colors">Odhlásit</button>
          </div>

          <div className="text-center mb-12">
              <h1 className="text-5xl font-bold text-gray-900 mb-4 tracking-tight">Maturitní testy</h1>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl mx-auto mb-16">
              <button onClick={handleSPSSelection} className="group relative overflow-hidden bg-white p-8 rounded-2xl shadow-lg border border-gray-100 hover:shadow-2xl hover:border-blue-300 transition-all duration-300 transform hover:-translate-y-1 text-center">
                  <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-500 to-indigo-600"></div>
                  <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform duration-300">
                      <svg className="w-12 h-12 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                  <h2 className="text-3xl font-bold text-gray-800 mb-2">SPS</h2>
                  <p className="text-gray-500">Stavba a provoz strojů</p>
              </button>
              <button onClick={handleSTTSelection} className="group relative overflow-hidden bg-white p-8 rounded-2xl shadow-lg border border-gray-100 hover:shadow-2xl hover:border-orange-300 transition-all duration-300 transform hover:-translate-y-1 text-center">
                  <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-orange-500 to-red-600"></div>
                  <div className="w-24 h-24 bg-orange-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform duration-300">
                      <svg className="w-12 h-12 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                  </div>
                  <h2 className="text-3xl font-bold text-gray-800 mb-2">STT</h2>
                  <p className="text-gray-500">Strojírenská technologie</p>
                  <p className="text-red-500 font-bold mt-4">Není hotové</p>
              </button>
          </div>

          <div className="w-full max-w-5xl mx-auto mb-10">
              <h2 className="text-center text-2xl font-bold text-slate-400 uppercase tracking-widest mb-10">Statistiky</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  <div className="animate-in fade-in slide-in-from-left duration-700">
                      <Leaderboard subject="SPS" variant="compact" currentUserId={currentUser.uid} />
                  </div>
                  <div className="animate-in fade-in slide-in-from-right duration-700 delay-150">
                      <Leaderboard subject="STT" variant="compact" currentUserId={currentUser.uid} />
                  </div>
              </div>
          </div>

          <footer className="mt-auto py-12 text-center text-[#94a3b8] text-base font-normal select-none">
            © 2026 Matyáš Korec | Verze 2.3.1
          </footer>
      </div>
      )}

      {subject && mode === AppMode.BATTLE_HUB && (
        <div className="max-w-4xl mx-auto min-h-screen flex flex-col p-4 md:p-8 animate-in zoom-in duration-200">
           <div className="flex justify-between items-center mb-8">
              <button onClick={() => setMode(AppMode.MENU)} className="text-gray-500 hover:text-gray-800 font-medium flex items-center gap-2">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Zpět do menu
              </button>
              <h1 className="text-3xl font-black text-gray-900 uppercase italic tracking-tighter">ARÉNA</h1>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-4">
              <button onClick={() => setMode(AppMode.BATTLE)} className="group relative overflow-hidden bg-white rounded-3xl p-8 shadow-xl border-2 border-transparent hover:border-blue-500 transition-all duration-300 text-left hover:shadow-2xl hover:-translate-y-1">
                 <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <span className="text-9xl">⚔️</span>
                 </div>
                 <div className="relative z-10">
                    <div className="w-16 h-16 bg-blue-100 rounded-2xl flex items-center justify-center mb-6 text-3xl shadow-sm group-hover:scale-110 transition-transform">⚔️</div>
                    <h2 className="text-2xl font-black text-gray-900 mb-2">1v1 Duel</h2>
                    <p className="text-gray-500 mb-4 font-medium">1v1 souboj v reálném čase.</p>
                 </div>
              </button>

              <button onClick={() => setMode(AppMode.SUDDEN_DEATH)} className="group relative overflow-hidden bg-gray-900 rounded-3xl p-8 shadow-xl border-2 border-transparent hover:border-red-500 transition-all duration-300 text-left hover:shadow-2xl hover:-translate-y-1">
                 <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <span className="text-9xl">☠️</span>
                 </div>
                 <div className="relative z-10">
                    <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center mb-6 text-3xl shadow-lg shadow-red-900/50 group-hover:scale-110 transition-transform">☠️</div>
                    <h2 className="text-2xl font-black text-white mb-2">Náhlá smrt</h2>
                    <p className="text-gray-400 mb-4 font-medium">Jedna chyba = konec, Hraje se o největší streak, omezeno časem.</p>
                 </div>
              </button>
           </div>
        </div>
      )}

      {subject && mode === AppMode.MENU && (
        <div className="max-w-6xl mx-auto min-h-screen flex flex-col p-4 md:p-8">
            <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                <div onClick={() => {setSubject(null); setBrowserSearch("");}} className="group cursor-pointer inline-flex items-center gap-2 px-5 py-2 rounded-full bg-white border border-gray-200 text-gray-600 font-medium text-sm shadow-sm hover:shadow-md hover:border-blue-300 hover:text-blue-600 transition-all duration-300">
                    <svg className="w-4 h-4 transition-transform group-hover:-translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Zpět na výběr předmětu
                </div>
                <div className="text-right">
                    <h1 className={`text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r ${subject === 'SPS' ? 'from-blue-700 to-indigo-600' : 'from-orange-600 to-red-600'}`}>Maturitní test {subject}</h1>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="space-y-4">
                    {subject === 'SPS' && (
                        <button onClick={() => setMode(AppMode.BATTLE_HUB)} className={getMenuButtonClass("bg-gradient-to-br from-gray-800 to-gray-900 text-white border-none")}>
                            <div className="bg-white/10 p-3 rounded-full border border-white/20">
                                <span className="text-2xl">🏆</span>
                            </div>
                            <div>
                                <div className="font-bold text-lg text-white uppercase tracking-wider">ARÉNA</div>
                                <div className="text-gray-400 text-sm font-normal">1v1 Duel & Náhlá smrt</div>
                            </div>
                        </button>
                    )}
                    <button onClick={() => setMode(AppMode.MOCK_TEST)} className={getMenuButtonClass("bg-white hover:bg-blue-50 text-blue-700")}>
                        <div className="bg-blue-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></div>
                        <div><div className="font-bold text-lg">Test nanečisto</div><div className="text-sm text-gray-500 font-normal">40 otázek • 30 minut</div></div>
                    </button>
                    <button onClick={() => setMode(AppMode.TRAINING)} className={getMenuButtonClass("bg-white hover:bg-green-50 text-green-700")}>
                        <div className="bg-green-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg></div>
                        <div><div className="font-bold text-lg">Náhodný trénink</div><div className="text-sm text-gray-500 font-normal">Okamžitá kontrola</div></div>
                    </button>
                </div>
                <div className="space-y-4">
                    <button onClick={() => setMode(AppMode.MISTAKES)} disabled={mistakesSPS.length === 0 && mistakesSTT.length === 0} className={getMenuButtonClass(currentMistakes.length > 0 ? "bg-white hover:bg-orange-50 text-orange-700" : "bg-gray-100 text-gray-400 cursor-not-allowed")}>
                        <div className={`${currentMistakes.length > 0 ? 'bg-orange-100' : 'bg-gray-200'} p-3 rounded-full`}><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></div>
                        <div><div className="font-bold text-lg">Oprava chyb</div><div className="text-sm font-normal">{currentMistakes.length} chyb v paměti</div></div>
                    </button>
                    <button onClick={() => { setMode(AppMode.BROWSER); setBrowserSearch(""); setExpandedIds(new Set()); }} className={getMenuButtonClass("bg-white hover:bg-indigo-50 text-indigo-700")}>
                        <div className="bg-indigo-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
                        <div><div className="font-bold text-lg">Prohlížet otázky</div><div className="text-sm text-gray-500 font-normal">Databáze {currentQuestions.length} otázek</div></div>
                    </button>
                </div>
            </div>
        </div>
      )}

      {subject && mode === AppMode.BROWSER && (
        <div className="max-w-4xl mx-auto p-4 md:p-8">
            <div className="flex items-center gap-4 mb-8 sticky top-0 bg-slate-50 py-4 z-20">
                <button 
                  onClick={() => { setMode(AppMode.MENU); setBrowserSearch(""); setExpandedIds(new Set()); }} 
                  className="p-2 text-gray-500 hover:text-blue-600 hover:bg-white rounded-full transition-all shadow-none hover:shadow-sm"
                  title="Zpět do menu"
                >
                    <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                </button>

                <div className="relative flex-1">
                    <input 
                        type="text" 
                        placeholder="Hledat otázku..." 
                        value={browserSearch}
                        onChange={(e) => setBrowserSearch(e.target.value)}
                        className="w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none bg-white shadow-sm transition-all"
                    />
                    <svg className="w-5 h-5 absolute left-4 top-3.5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>

                <button 
                    onClick={expandedIds.size > 0 ? collapseAll : expandAllVisible}
                    className="flex items-center gap-2 px-5 py-3 bg-[#f0f7ff] text-[#2563eb] rounded-xl font-bold hover:bg-blue-100 transition-colors shadow-sm whitespace-nowrap"
                >
                    {expandedIds.size > 0 ? (
                        <>
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                          Zabalit vše
                        </>
                    ) : (
                        <>
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                          Rozbalit vše
                        </>
                    )}
                </button>
            </div>

            <div className="space-y-4">
                {filteredBrowserQuestions.length > 0 ? (
                    filteredBrowserQuestions.map(q => (
                        <BrowserQuestionItem 
                            key={q.id} 
                            question={q} 
                            isExpanded={expandedIds.has(q.id)} 
                            onToggle={() => toggleExpand(q.id)}
                            onReportRequest={(id) => setReportingQuestionId(id)}
                        />
                    ))
                ) : (
                    <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
                        <p className="text-gray-400">Žádné otázky neodpovídají hledání.</p>
                    </div>
                )}
            </div>
        </div>
      )}

      {subject && mode === AppMode.BATTLE && currentUser && (
          <BattleManager 
            currentUser={currentUser} 
            subject={subject} 
            stats={statsSPS}
            onExit={() => setMode(AppMode.MENU)} 
          />
      )}

      {subject && mode === AppMode.SUDDEN_DEATH && currentUser && (
          <SuddenDeathGame 
            initialQuestions={currentQuestions}
            currentUser={currentUser}
            onExit={() => setMode(AppMode.MENU)}
          />
      )}

      {subject && (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) && (
          <TestRunner key={subject + mode} mode={mode} mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined} onComplete={handleTestComplete} onExit={() => setMode(AppMode.MENU)} onReportRequest={(id) => setReportingQuestionId(id)} initialQuestionsForMode={currentQuestions} initialQuestions={mode === AppMode.REVIEW ? lastTestQuestions : undefined} initialAnswers={mode === AppMode.REVIEW ? lastUserAnswers : undefined} subject={subject} />
      )}
    </div>
  );
};

export default App;

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctAnswerIndex: number; // 0-3
  acceptableAnswerIndex?: number; // Alternativní uznatelná odpověď
  imageUrl?: string;
}

export type Subject = 'SPS' | 'STT';

export enum AppMode {
  MENU = 'MENU',
  MOCK_TEST = 'MOCK_TEST',
  TRAINING = 'TRAINING',
  BROWSER = 'BROWSER',
  MISTAKES = 'MISTAKES',
  REVIEW = 'REVIEW',
  LEADERBOARD = 'LEADERBOARD',
  BATTLE_HUB = 'BATTLE_HUB', // Rozcestník pro bojové módy
  BATTLE = 'BATTLE', // 1v1
  SUDDEN_DEATH = 'SUDDEN_DEATH', // Náhlá smrt
}

export interface TestResult {
  score: number;
  total: number;
  passed: boolean;
  mistakes: number[];
  timeElapsed: number;
  userAnswers: Record<number, number>;
  questionsUsed: Question[];
}

export interface SubjectStats {
  testsTaken: number;
  totalPoints: number;
  totalMaxPoints: number;
  bestScorePercent: number;
  // Limity pro bitvy
  battlesPlayedToday?: number;
  lastBattleDate?: string; // YYYY-MM-DD
  // Statistiky pro Sudden Death
  bestStreak?: number;
}

export interface LeaderboardUser {
  uid: string; // Pridano pro identifikaci
  displayName: string;
  statsSPS?: SubjectStats;
  statsSTT?: SubjectStats;
}

export interface QuestionReport {
  questionId: number;
  subject: Subject;
  reason: string;
  userName: string;
  timestamp: string;
}

// Rozhraní pro 1v1 Bitvu
export interface BattlePlayerData {
  uid: string;
  displayName: string;
  progress: number; // 0-20
  score: number;
  finished: boolean;
  ready: boolean;
}

export interface BattleRoom {
  id: string;
  code: string;
  subject: Subject;
  status: 'WAITING' | 'STARTING' | 'IN_PROGRESS' | 'FINISHED';
  questions: number[]; // Seznam ID otázek
  players: Record<string, BattlePlayerData>;
  createdAt: any;
  expiresAt?: number; // Timestamp vypršení hry (ms)
}

import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack?: () => void;
  variant?: 'full' | 'compact'; // 'full' = celá stránka, 'compact' = widget do menu
  currentUserId?: string;
}

type SortType = 'SCORE' | 'GRIND' | 'STREAK';

export const Leaderboard: React.FC<Props> = ({ subject, onBack, variant = 'full', currentUserId }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ uid: doc.id, displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ uid: doc.id, displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error instanceof Error ? error.message : error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    if (sortType === 'SCORE') {
      // Primárně podle nejlepšího skóre
      if (statsB.bestScorePercent !== statsA.bestScorePercent) {
        return statsB.bestScorePercent - statsA.bestScorePercent;
      }
      return (statsB.bestStreak || 0) - (statsA.bestStreak || 0);
    } else if (sortType === 'GRIND') {
      // Primárně podle počtu testů
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      return statsB.bestScorePercent - statsA.bestScorePercent;
    } else {
      // Primárně podle streaku
      const streakA = statsA.bestStreak || 0;
      const streakB = statsB.bestStreak || 0;
      if (streakB !== streakA) return streakB - streakA;
      return statsB.bestScorePercent - statsA.bestScorePercent;
    }
  });

  // Logika pro zobrazení
  let displayUsers = sortedUsers;
  let currentUserRankIndex = -1;

  if (currentUserId) {
      currentUserRankIndex = sortedUsers.findIndex(u => u.uid === currentUserId);
  }

  // V kompaktním režimu ukážeme jen TOP 5, ale pokud je uživatel níže, přidáme ho nakonec
  if (variant === 'compact') {
      displayUsers = sortedUsers.slice(0, 5);

      // Pokud je uživatel v seznamu, ale není v TOP 5, přidáme ho
      if (currentUserRankIndex > 4) {
          // Přidáme "..." (reprezentováno null) a pak uživatele
          // Použijeme typ any v poli pro zjednodušení renderování oddělovače
          displayUsers = [...displayUsers, null as any, sortedUsers[currentUserRankIndex]];
      }
  }

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300";
    if (index === 1) return "bg-gray-100 text-gray-700 border-gray-300";
    if (index === 2) return "bg-orange-100 text-orange-800 border-orange-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  // Helper funkce pro výpočet průměru
  const calculateAverage = (totalPoints: number, totalMaxPoints: number) => {
      if (!totalMaxPoints || totalMaxPoints === 0) return 0;
      return Math.round((totalPoints / totalMaxPoints) * 100);
  };

  return (
    <div className={`${variant === 'full' ? 'max-w-6xl mx-auto p-4 min-h-screen' : 'w-full h-full flex flex-col'}`}>

      {/* Header */}
      <div className={`flex items-center justify-between ${variant === 'full' ? 'mb-8' : 'mb-4'}`}>
        {variant === 'full' && onBack && (
            <button 
                onClick={onBack}
                className="flex items-center text-gray-500 hover:text-gray-900 transition-colors"
            >
                <svg className="w-6 h-6 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Zpět
            </button>
        )}
        <h1 className={`font-bold ${variant === 'full' ? 'text-2xl' : 'text-lg'} ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            {variant === 'full' ? `Žebříček ${subject}` : `Top ${subject}`}
        </h1>
      </div>

      {/* Přepínač řazení pouze pro plnou verzi */}
      {variant === 'full' && (
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
            <div className="text-gray-500 text-sm">
                Řadit podle:
            </div>
            <div className="flex flex-wrap gap-2 bg-gray-100 p-1 rounded-lg">
                <button 
                    onClick={() => setSortType('SCORE')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'SCORE' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🎯</span> Nejlepší výkon
                </button>
                <button 
                    onClick={() => setSortType('GRIND')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'GRIND' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>💪</span> Počet testů
                </button>
                <button 
                    onClick={() => setSortType('STREAK')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'STREAK' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🔥</span> Streak
                </button>
            </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Načítám data...</div>
      ) : sortedUsers.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl shadow-sm border border-gray-200 border-dashed">
            <p className="text-gray-400 text-sm">Zatím žádné statistiky.</p>
        </div>
      ) : (
        <div className={`bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex-1 ${variant === 'compact' ? 'text-sm' : ''}`}>
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-xs uppercase tracking-wider border-b border-gray-200">
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center w-8`}>#</th>
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'}`}>Jméno</th>

                            {/* Sloupce - Plná verze (více místa) */}
                            {variant === 'full' && (
                                <>
                                    <th className="px-6 py-4 text-center whitespace-nowrap" title="Počet dokončených testů">Počet testů</th>
                                    <th className="px-6 py-4 text-center whitespace-nowrap" title="Průměr ze všech testů">Průměr</th>
                                    <th className="px-6 py-4 text-center whitespace-nowrap" title="Nejlepší výsledek testu">Nejlepší</th>
                                    <th className="px-6 py-4 text-center text-red-600 whitespace-nowrap" title="Největší skóre v náhlé smrti">Sudden Death 🔥</th>
                                </>
                            )}

                            {/* Sloupce - Kompaktní verze */}
                            {variant === 'compact' && (
                                <>
                                    <th className="px-1 py-2 text-center text-[10px] w-8" title="Počet testů">Testy</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8" title="Průměr">Ø</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-10" title="Nejlepší">Max</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8 text-red-600" title="Streak">🔥</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {displayUsers.map((user, i) => {
                            // Render oddělovače (pokud je user null)
                            if (!user) {
                                return (
                                    <tr key="separator" className="bg-gray-50">
                                        <td colSpan={variant === 'compact' ? 6 : 6} className="text-center py-1 text-gray-400 text-xs">
                                            • • •
                                        </td>
                                    </tr>
                                );
                            }

                            // Musíme najít skutečný rank v sortedUsers poli
                            const realRank = sortedUsers.findIndex(u => u.uid === user.uid);
                            const isMe = user.uid === currentUserId;

                            const stats = getStats(user)!;
                            const avgPercent = calculateAverage(stats.totalPoints, stats.totalMaxPoints);
                            const bestStreak = stats.bestStreak || 0;

                            return (
                                <tr key={user.uid} className={`transition-colors ${isMe ? 'bg-blue-50/80 border-l-4 border-l-blue-500' : 'hover:bg-gray-50'}`}>
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center`}>
                                        <div className={`${variant === 'compact' ? 'w-6 h-6 text-xs' : 'w-8 h-8'} rounded-full flex items-center justify-center mx-auto font-bold border ${getMedalColor(realRank)}`}>
                                            {realRank + 1}
                                        </div>
                                    </td>
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} font-medium text-gray-900 truncate max-w-[100px] sm:max-w-none`}>
                                        {user.displayName} {isMe && <span className="text-[10px] text-blue-600 ml-1">(Ty)</span>}
                                    </td>

                                    {/* Plná verze tabulky */}
                                    {variant === 'full' && (
                                        <>
                                            <td className="px-6 py-4 text-center text-gray-600 font-medium">
                                                {stats.testsTaken}x
                                            </td>
                                            <td className="px-6 py-4 text-center font-medium text-blue-600">
                                                {avgPercent}%
                                            </td>
                                            <td className="px-6 py-4 text-center font-bold text-gray-800 text-lg">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-6 py-4 text-center font-black text-red-600 text-lg">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}

                                    {/* Kompaktní verze widgetu */}
                                    {variant === 'compact' && (
                                        <>
                                            <td className="px-1 py-2 text-center text-xs text-gray-500">
                                                {stats.testsTaken}
                                            </td>
                                            <td className="px-1 py-2 text-center text-xs font-medium text-blue-600">
                                                {avgPercent}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-bold text-gray-800">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-black text-red-600">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            {variant === 'compact' && sortedUsers.length > 5 && currentUserRankIndex <= 4 && (
                <div 
                    onClick={onBack} 
                    className="bg-gray-50 p-2 text-center text-xs text-gray-500 hover:text-blue-600 hover:bg-gray-100 cursor-pointer border-t border-gray-100 transition-colors"
                >
                    Zobrazit všech {sortedUsers.length} studentů...
                </div>
            )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { QUESTIONS_SPS, QUESTIONS_STT } from './constants';
import { AppMode, TestResult, Question, Subject } from './types';
import { TestRunner } from './components/TestRunner';
import { BrowserQuestionItem } from './components/BrowserQuestionItem';
import { LoginScreen } from './components/LoginScreen';
import { Leaderboard } from './components/Leaderboard';
import { SPSInfoModal } from './components/SPSInfoModal';
import { STTInfoModal } from './components/STTInfoModal';
import { ReportModal } from './components/ReportModal';
import { BattleManager } from './components/BattleManager';
import { SuddenDeathGame } from './components/SuddenDeathGame';
import { AppUser } from './users';
import { db, auth } from './firebaseConfig';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AppUser | null>(null);
  const [loadingUser, setLoadingUser] = useState(true);

  const [subject, setSubject] = useState<Subject | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.MENU);

  const [showSPSPopup, setShowSPSPopup] = useState(false);
  const [showSTTPopup, setShowSTTPopup] = useState(false);
  const [reportingQuestionId, setReportingQuestionId] = useState<number | null>(null);

  const [mistakesSPS, setMistakesSPS] = useState<number[]>([]);
  const [mistakesSTT, setMistakesSTT] = useState<number[]>([]);
  const [statsSPS, setStatsSPS] = useState<any>(null);

  const [lastResult, setLastResult] = useState<TestResult | null>(null);
  const [browserSearch, setBrowserSearch] = useState("");
  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());
  const [lastTestQuestions, setLastTestQuestions] = useState<Question[]>([]);
  const [lastUserAnswers, setLastUserAnswers] = useState<Record<number, number>>({});

  useEffect(() => {
      if(!auth) {
          setLoadingUser(false);
          return;
      }
      const unsubscribe = onAuthStateChanged(auth, (user) => {
          if (user) {
              setCurrentUser({
                  uid: user.uid,
                  email: user.email || '',
                  displayName: user.displayName || 'Student'
              });
          } else {
              setCurrentUser(null);
          }
          setLoadingUser(false);
      });
      return () => unsubscribe();
  }, []);

  const handleLogout = () => {
      localStorage.removeItem('app_session_id');
      if(auth) signOut(auth);
      setSubject(null);
      setMode(AppMode.MENU);
      setLastResult(null);
  };

  useEffect(() => {
    if (currentUser && db) {
        const userDocRef = doc(db, "users", currentUser.uid);

        // OPRAVA: Uložíme jméno uživatele do databáze, aby bylo vidět v žebříčku
        setDoc(userDocRef, { 
            displayName: currentUser.displayName,
            email: currentUser.email 
        }, { merge: true }).catch(err => console.error("Chyba při ukládání jména:", err));

        const unsubDoc = onSnapshot(userDocRef, (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                setMistakesSPS(data.mistakesSPS || []);
                setMistakesSTT(data.mistakesSTT || []);
                setStatsSPS(data.statsSPS || null);
            }
        });
        return () => unsubDoc();
    }
  }, [currentUser]);

  const currentQuestions = useMemo(() => {
    if (subject === 'SPS') return QUESTIONS_SPS;
    if (subject === 'STT') return QUESTIONS_STT;
    return [];
  }, [subject]);

  const filteredBrowserQuestions = useMemo(() => {
    if (mode !== AppMode.BROWSER) return [];
    const search = browserSearch.toLowerCase().trim();
    if (!search) return currentQuestions;
    return currentQuestions.filter(q => 
        q.id.toString() === search || 
        q.text.toLowerCase().includes(search)
    );
  }, [mode, currentQuestions, browserSearch]);

  const currentMistakes = subject === 'SPS' ? mistakesSPS : mistakesSTT;

  const setMistakes = async (newMistakes: number[]) => {
      if (subject === 'SPS') setMistakesSPS(newMistakes);
      else if (subject === 'STT') setMistakesSTT(newMistakes);
      if (currentUser && db) {
          const userDocRef = doc(db, "users", currentUser.uid);
          const updateData = subject === 'SPS' ? { mistakesSPS: newMistakes } : { mistakesSTT: newMistakes };
          await setDoc(userDocRef, updateData, { merge: true });
      }
  };

  const handleSPSSelection = () => {
    const isHidden = localStorage.getItem('hideSPSInfo');
    if (isHidden) { setSubject('SPS'); setBrowserSearch(""); } 
    else { setShowSPSPopup(true); }
  };

  const handleSTTSelection = () => {
    const isHidden = localStorage.getItem('hideSTTInfo');
    if (isHidden) { setSubject('STT'); setBrowserSearch(""); } 
    else { setShowSTTPopup(true); }
  };

  const handleTestComplete = (result: TestResult) => {
    setLastResult(result);
    if (mode === AppMode.MOCK_TEST) {
        setMistakes(Array.from(new Set([...currentMistakes, ...result.mistakes])));
        setLastTestQuestions(result.questionsUsed);
        setLastUserAnswers(result.userAnswers);
    } else if (mode === AppMode.MISTAKES) {
        setMistakes(result.mistakes);
    }
    setMode(AppMode.MENU);
  };

  const toggleExpand = (id: number) => {
    setExpandedIds(prev => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
    });
  };

  const expandAllVisible = () => {
    const allIds = filteredBrowserQuestions.map(q => q.id);
    setExpandedIds(new Set(allIds));
  };

  const collapseAll = () => {
    setExpandedIds(new Set());
  };

  const getMenuButtonClass = (color: string) => 
    `w-full p-6 rounded-xl shadow-md transition-all duration-300 transform hover:-translate-y-1 hover:shadow-xl flex flex-col items-center justify-center gap-3 text-center border border-gray-100 ${color}`;

  if (loadingUser) return <div className="min-h-screen flex items-center justify-center text-gray-500">Načítám...</div>;
  if (!currentUser) return <LoginScreen onLogin={(user) => setCurrentUser(user)} />;

  return (
    <div className="min-h-screen bg-slate-50 text-gray-900 font-sans relative">
      <div className="fixed bottom-2 right-4 text-[10px] text-gray-300 pointer-events-none z-[100] select-none">
          User: {currentUser.displayName}
      </div>

      {reportingQuestionId !== null && subject && (
        <ReportModal questionId={reportingQuestionId} subject={subject} userName={currentUser.displayName} onClose={() => setReportingQuestionId(null)} />
      )}

      {showSPSPopup && (
        <SPSInfoModal onConfirm={() => { setShowSPSPopup(false); setSubject('SPS'); setBrowserSearch(""); }} />
      )}

      {showSTTPopup && (
        <STTInfoModal onConfirm={() => { setShowSTTPopup(false); setSubject('STT'); setBrowserSearch(""); }} />
      )}

      {lastResult && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl animate-in fade-in zoom-in duration-300">
                <div className="text-center">
                    <div className={`mx-auto w-20 h-20 rounded-full flex items-center justify-center mb-4 ${lastResult.passed ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {lastResult.passed ? <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg> : <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>}
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-1">{lastResult.passed ? "Prošel(a) jsi!" : "Neprošel(a) jsi"}</h2>
                    <p className="text-gray-500 mb-6">Skóre: <span className="font-bold text-gray-800">{Math.round((lastResult.score / lastResult.total) * 100)}%</span> ({lastResult.score}/{lastResult.total})</p>
                    <button onClick={() => setLastResult(null)} className="w-full py-3 rounded-lg bg-gray-900 text-white font-bold hover:bg-gray-800 transition-colors">Zavřít</button>
                </div>
            </div>
        </div>
      )}

      {!subject && (
      <div className="max-w-7xl mx-auto min-h-screen flex flex-col p-6">
          <div className="flex justify-end items-center gap-4 mb-12">
              <span className="text-gray-600 font-medium bg-white px-4 py-2 rounded-full shadow-sm border border-gray-100">👤 {currentUser.displayName}</span>
              <button onClick={handleLogout} className="text-sm text-red-500 hover:text-red-700 font-semibold border border-red-200 px-4 py-2 rounded-full hover:bg-red-50 transition-colors">Odhlásit</button>
          </div>

          <div className="text-center mb-12">
              <h1 className="text-5xl font-bold text-gray-900 mb-4 tracking-tight">Maturitní testy</h1>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl mx-auto mb-16">
              <button onClick={handleSPSSelection} className="group relative overflow-hidden bg-white p-8 rounded-2xl shadow-lg border border-gray-100 hover:shadow-2xl hover:border-blue-300 transition-all duration-300 transform hover:-translate-y-1 text-center">
                  <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-500 to-indigo-600"></div>
                  <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform duration-300">
                      <svg className="w-12 h-12 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                  <h2 className="text-3xl font-bold text-gray-800 mb-2">SPS</h2>
                  <p className="text-gray-500">Stavba a provoz strojů</p>
              </button>
              <button onClick={handleSTTSelection} className="group relative overflow-hidden bg-white p-8 rounded-2xl shadow-lg border border-gray-100 hover:shadow-2xl hover:border-orange-300 transition-all duration-300 transform hover:-translate-y-1 text-center">
                  <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-orange-500 to-red-600"></div>
                  <div className="w-24 h-24 bg-orange-50 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform duration-300">
