                )}
            </div>
        </div>
      )}

      {subject && mode === AppMode.BATTLE && currentUser && (
          <BattleManager 
            currentUser={currentUser} 
            subject={subject} 
            stats={statsSPS}
            onExit={() => setMode(AppMode.MENU)} 
          />
      )}

      {subject && mode === AppMode.SUDDEN_DEATH && currentUser && (
          <SuddenDeathGame 
            initialQuestions={currentQuestions}
            currentUser={currentUser}
