const checkHasImage = (id: number, config: (number | [number, number])[]): boolean => {
  return config.some(item => {
    if (Array.isArray(item)) {
      return id >= item[0] && id <= item[1];
    }
    return id === item;
  });
};

const parseQuestions = (raw: any[], subject: 'SPS' | 'STT'): Question[] => {
  const imageConfig = subject === 'SPS' ? SPS_IMAGE_IDS : STT_IMAGE_IDS;

  return raw.map(item => {
    const [id, text, options, correct, acceptable] = item;

    const hasImage = checkHasImage(id, imageConfig);

    const imagePath = hasImage 
        ? `/images/${subject.toLowerCase()}/q${id}.png` 
        : undefined;

    return {
      id,
      text,
      options,
      correctAnswerIndex: correct,
      acceptableAnswerIndex: acceptable,
      imageUrl: imagePath
    };
  });
};

export const QUESTIONS_SPS: Question[] = parseQuestions(RAW_SPS, 'SPS');
export const QUESTIONS_STT: Question[] = parseQuestions(RAW_STT, 'STT');

// Filtrovaný seznam pro Testy a Arénu (bez vadné otázky 254)
export const QUESTIONS_SPS_FOR_TESTS: Question[] = QUESTIONS_SPS.filter(q => q.id !== 254);

import React, { useState, useEffect } from 'react';
import { Question, AppMode } from '../types';

// Definice pro globální objekt KaTeX, který načítáme v index.html
declare global {
  interface Window {
    katex: any;
  }
}

interface Props {
  question: Question;
  mode: AppMode;
  onAnswer: (questionId: number, selectedIndex: number, isCorrect: boolean) => void;
  showFeedback: boolean;
  userAnswer?: number | null;
  onReportRequest?: (qId: number) => void;
}

export const QuestionCard: React.FC<Props> = ({
  question,
  mode,
  onAnswer,
  showFeedback,
  userAnswer,
  onReportRequest
}) => {
  const [selected, setSelected] = useState<number | null>(userAnswer ?? null);
  const [imgError, setImgError] = useState(false);
  const [currentImgSrc, setCurrentImgSrc] = useState<string | undefined>(question.imageUrl);

  useEffect(() => {
    setSelected(userAnswer ?? null);
    setImgError(false);
    setCurrentImgSrc(question.imageUrl);
  }, [question, userAnswer]);

  const handleSelect = (index: number) => {
    if (showFeedback && selected !== null) return;
    if (mode === AppMode.REVIEW) return;

    setSelected(index);
    // Považujeme za správné, pokud je to preference NEBO uznatelná alternativa
    const isCorrect = index === question.correctAnswerIndex || index === question.acceptableAnswerIndex;
    onAnswer(question.id, index, isCorrect);
  };

  const handleImageError = () => {
      if (!currentImgSrc) return;

      // Zkoušíme postupně: .png -> .PNG -> .jpg -> .JPG
      if (currentImgSrc.endsWith('.png')) {
          setCurrentImgSrc(currentImgSrc.replace('.png', '.PNG'));
      } else if (currentImgSrc.endsWith('.PNG')) {
          setCurrentImgSrc(currentImgSrc.replace('.PNG', '.jpg'));
      } else if (currentImgSrc.endsWith('.jpg')) {
          setCurrentImgSrc(currentImgSrc.replace('.jpg', '.JPG'));
      } else {
          setImgError(true);
      }
  };

  // --- VYLEPŠENÝ PARSER MATEMATICKÝCH VZORCŮ S KATEX ---
  const renderMathText = (text: string) => {
    if (!text) return text;

    // 1. PRIORITA: HTML (např. pro červený text v STT otázce 273)
    if (text.includes('<') && text.includes('>')) {
        return <span dangerouslySetInnerHTML={{ __html: text }} />;
    }

    // 2. PRIORITA: KaTeX (Matematika)
    const useKatex = text.includes('sqrt') || (text.includes('_') && text.includes('^'));

    if (useKatex && window.katex) {
        try {
            let latex = text;
            latex = latex.replace(/sqrt\((.+?)\)/g, '\\sqrt{$1}');
            latex = latex.replace(/(\d|[a-zA-Z])x([a-zA-Z]|\d)/g, '$1 \\cdot $2');
            latex = latex.replace(/_([a-zA-Z0-9]+)/g, '_{$1}');

            const html = window.katex.renderToString(latex, {
                throwOnError: false,
                displayMode: false
            });

            return <span dangerouslySetInnerHTML={{ __html: html }} />;
        } catch (e) {
            console.error("KaTeX error:", e);
        }
    }

    // 3. FALLBACK: Jednoduché náhrady
    let html = text;
    if (text.includes('_') || text.includes('^')) {
         html = html.replace(/(\d)x([A-Z])/g, '$1&times;$2');
         html = html.replace(/(\d)x(\d)/g, '$1&times;$2');
         html = html.replace(/ x /g, ' &times; ');
         html = html.replace(/([a-zA-Z0-9])_([a-zA-Z0-9]+)/g, '$1<sub>$2</sub>');
         html = html.replace(/\^([0-9]+)/g, '<sup>$1</sup>');
         return <span dangerouslySetInnerHTML={{ __html: html }} />;
    }

    return text;
  };

  const getOptionClass = (index: number) => {
    const base = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center gap-3 ";

    if (mode === AppMode.MOCK_TEST) {
      return base + (selected === index 
        ? "border-blue-500 bg-blue-50 text-blue-900 ring-2 ring-blue-200" 
        : "border-gray-200 hover:bg-gray-50 text-gray-700");
    }

    if (showFeedback || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) {
        if (selected === null && mode !== AppMode.REVIEW) return base + "border-gray-200 hover:bg-gray-50 text-gray-700";

        // 1. Preferovaná správná odpověď (Zelená)
        if (index === question.correctAnswerIndex) {
            return base + "border-green-500 bg-green-50 text-green-900 ring-2 ring-green-200 font-medium";
        }
        // 2. Uznatelná alternativní odpověď (Žlutá)
        if (index === question.acceptableAnswerIndex) {
            // Pokud je vybrána uživatelem, svítí žlutě. V Review módu svítí žlutě vždy.
            if (selected === index || mode === AppMode.REVIEW || mode === AppMode.TRAINING) {
               return base + "border-yellow-500 bg-yellow-50 text-yellow-900 ring-2 ring-yellow-200 font-medium";
            }
        }
        // 3. Špatná vybraná odpověď (Červená)
        if (selected === index && index !== question.correctAnswerIndex && index !== question.acceptableAnswerIndex) {
            return base + "border-red-500 bg-red-50 text-red-900 ring-2 ring-red-200";
        }
        return base + "border-gray-200 opacity-60";
    }

    return base + "border-gray-200";
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 max-w-3xl mx-auto mb-6">
      <div className="flex justify-between items-start mb-4 gap-4">
        <h3 className="text-lg font-semibold text-gray-900 leading-relaxed flex-1">
          <span className="text-blue-600 mr-2">#{question.id}</span>
          {renderMathText(question.text)}
        </h3>
        {onReportRequest && (
          <button 
            onClick={() => onReportRequest(question.id)}
            className="text-gray-300 hover:text-red-400 p-1 transition-colors group"
            title="Nahlásit chybu v otázce"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 21v-4m0 0V5a2 2 0 012-2h6.5l1 1H21l-3 6 3 6h-8.5l-1-1H5a2 2 0 00-2 2zm9-13.5V9" /></svg>
          </button>
        )}
      </div>

      {question.imageUrl && !imgError && currentImgSrc && (
        <div className="mb-6 rounded-lg overflow-hidden border border-gray-200 bg-gray-50 min-h-[200px] flex items-center justify-center relative">
          <img 
            src={currentImgSrc} 
            alt="Ilustrace k otázce" 
            className="w-full h-auto max-h-80 object-contain mx-auto"
            onError={handleImageError}
            loading="lazy"
          />
        </div>
      )}

      {question.imageUrl && imgError && (
          <div className="mb-6 p-4 text-center text-sm text-red-400 italic bg-red-50 rounded-lg border border-red-100">
             Obrázek se nepodařilo načíst (zkoušeno .png, .PNG, .jpg)
          </div>
      )}

      <div className="space-y-3">
        {question.options.map((opt, idx) => (
          <button
            key={idx}
            onClick={() => handleSelect(idx)}
            disabled={((mode === AppMode.TRAINING || mode === AppMode.MISTAKES) && selected !== null) || mode === AppMode.REVIEW}
            className={getOptionClass(idx)}
          >
            <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 
                ${selected === idx ? 'border-current' : 'border-gray-300'}`}>
                {selected === idx && <div className="w-2.5 h-2.5 rounded-full bg-current" />}
            </div>
            <span className="flex-1">{renderMathText(opt)}</span>
          </button>
        ))}
      </div>

      {/* Speciální vysvětlení pro vybrané otázky s více správnými odpověďmi nebo faktickými chybami */}
      {((question.id === 224) || (question.id === 422) || (question.id === 253) || (question.id === 254)) && (showFeedback || mode === AppMode.REVIEW || mode === AppMode.BROWSER || (selected !== null && mode !== AppMode.MOCK_TEST)) && (
        <div className="mt-4 p-3 bg-blue-50 rounded-lg border border-blue-100">
          <p className="text-[11px] text-blue-700 italic">
            {question.id === 224 && "Poznámka: Pokud vyberete odpověď C, je také uznána jako správná. Odpověď A je však technicky přesnější preference."}
            {question.id === 422 && "Poznámka: Odpovědi B i D jsou v tomto testu identické a obě jsou uznávány jako správné."}
            {question.id === 253 && "Poznámka: Správná odpověď by měla být: Třecí síla je větší než setrvačná. V tomto testu je původní odpověď označena jako uznatelná."}
            {question.id === 254 && "Poznámka: Žádná odpověď není správně. Tato otázka je v ostrých testech vyřazena."}
          </p>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Question, AppMode, TestResult } from '../types';
import { QuestionCard } from './QuestionCard';
import { db, auth } from '../firebaseConfig';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { QUESTIONS_SPS_FOR_TESTS } from '../constants';

interface Props {
  mode: AppMode;
  mistakeIds?: number[]; // IDs for "Oprava chyb" mode
  onComplete: (result: TestResult) => void;
  onExit: () => void;
  onReportRequest?: (qId: number) => void;

  // The full dataset for the current subject
  initialQuestionsForMode: Question[];

  // New props for Review Mode
  initialQuestions?: Question[];
  initialAnswers?: Record<number, number>;
  subject?: 'SPS' | 'STT'; // Potřebujeme vědět předmět pro ukládání statistik
}

export const TestRunner: React.FC<Props> = ({ mode, mistakeIds, onComplete, onExit, onReportRequest, initialQuestionsForMode, initialQuestions, initialAnswers, subject }) => {
  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);
  const [answers, setAnswers] = useState<Record<number, number>>({}); // qId -> selectedIndex
  const [timeLeft, setTimeLeft] = useState(30 * 60); // 30 mins in seconds
  const [currentIndex, setCurrentIndex] = useState(0);

  // Initialize Test
  useEffect(() => {
    let q: Question[] = [];

    if (initialQuestions && mode === AppMode.REVIEW) {
        q = initialQuestions;
        if (initialAnswers) {
            setAnswers(initialAnswers);
        }
    } else if (mode === AppMode.MOCK_TEST) {
      // PRO MOCK TEST POUŽÍVÁME FILTROVANÝ SEZNAM (BEZ Q254)
      const dataset = subject === 'SPS' ? QUESTIONS_SPS_FOR_TESTS : initialQuestionsForMode;
      const shuffled = [...dataset].sort(() => 0.5 - Math.random());
      q = shuffled.slice(0, 40);
    } else if (mode === AppMode.MISTAKES && mistakeIds) {
      q = initialQuestionsForMode.filter(q => mistakeIds.includes(q.id));
    } else if (mode === AppMode.TRAINING) {
      // Random training
      q = [...initialQuestionsForMode].sort(() => 0.5 - Math.random());
    } else {
        q = [...initialQuestionsForMode];
    }
    setCurrentQuestions(q);
  }, [mode, mistakeIds, initialQuestions, initialAnswers, initialQuestionsForMode, subject]);

  // Timer Logic (Only for Mock Test)
  useEffect(() => {
    if (mode !== AppMode.MOCK_TEST) return;

    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          clearInterval(timer);
          finishTest();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [mode]); // eslint-disable-next-line react-hooks/exhaustive-deps

  const handleAnswer = (qId: number, idx: number, isCorrect: boolean) => {
    setAnswers(prev => ({ ...prev, [qId]: idx }));
  };

  const saveStats = async (score: number, total: number) => {
      if (mode !== AppMode.MOCK_TEST || !subject || !auth.currentUser) return;

      try {
          const userRef = doc(db, "users", auth.currentUser.uid);
          const userSnap = await getDoc(userRef);

          if (userSnap.exists()) {
              const data = userSnap.data();
              const fieldName = subject === 'SPS' ? 'statsSPS' : 'statsSTT';
              const currentStats = data[fieldName] || {
                  testsTaken: 0,
                  totalPoints: 0,
                  totalMaxPoints: 0,
                  bestScorePercent: 0
              };

              const currentPercent = (score / total) * 100;

              const newStats = {
                  testsTaken: currentStats.testsTaken + 1,
                  totalPoints: currentStats.totalPoints + score,
                  totalMaxPoints: currentStats.totalMaxPoints + total,
                  bestScorePercent: Math.max(currentStats.bestScorePercent, currentPercent)
              };

              await setDoc(userRef, { [fieldName]: newStats }, { merge: true });
          }
      } catch (e) {
          console.error("Chyba při ukládání statistik:", e instanceof Error ? e.message : e);
      }
  };

  const finishTest = async () => {
    let score = 0;
    const mistakes: number[] = [];

    currentQuestions.forEach(q => {
      const userAns = answers[q.id];
      // Uznáváme jak preferovanou správnou (correctAnswerIndex), tak uznatelnou alternativu (acceptableAnswerIndex)
      const isCorrect = userAns === q.correctAnswerIndex || (q.acceptableAnswerIndex !== undefined && userAns === q.acceptableAnswerIndex);

      if (isCorrect) {
        score++;
      } else {
        mistakes.push(q.id);
      }
    });

    const total = currentQuestions.length;
    const percentage = total === 0 ? 0 : (score / total) * 100;
    const passed = percentage >= 44;

    saveStats(score, total);

    onComplete({
      score,
      total,
      passed,
      mistakes,
      timeElapsed: (30 * 60) - timeLeft,
      userAnswers: answers,
      questionsUsed: currentQuestions
    });
  };

  if (currentQuestions.length === 0) {
    return (
        <div className="text-center p-12">
            <h2 className="text-xl font-bold text-gray-700">Žádné otázky k zobrazení.</h2>
            <p className="text-gray-500 mb-4">V tomto režimu nejsou dostupné žádné otázky.</p>
            <button onClick={onExit} className="text-blue-600 underline">Zpět do menu</button>
        </div>
    );
  }

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const currentQ = currentQuestions[currentIndex];

  return (
    <div className="max-w-4xl mx-auto w-full">
      {/* Header Bar */}
      <div className="bg-white sticky top-0 z-10 shadow-sm border-b border-gray-200 px-6 py-4 mb-6 flex justify-between items-center rounded-b-xl">
        <div className="flex items-center gap-4">
            <button onClick={onExit} className="text-gray-500 hover:text-gray-900 transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </button>
            <div>
                <h2 className="font-bold text-gray-800">
                    {mode === AppMode.MOCK_TEST ? 'Test nanečisto' : 
                     mode === AppMode.TRAINING ? 'Náhodný trénink' : 
                     mode === AppMode.MISTAKES ? 'Oprava chyb' : 
                     mode === AppMode.REVIEW ? 'Kontrola testu' : 'Test'}
                </h2>
                <div className="text-sm text-gray-500">
                    Otázka {currentIndex + 1} z {currentQuestions.length}
                </div>
            </div>
        </div>

        {mode === AppMode.MOCK_TEST && (
            <div className={`font-mono text-xl font-bold ${timeLeft < 300 ? 'text-red-600' : 'text-blue-600'}`}>
                {formatTime(timeLeft)}
            </div>
        )}
      </div>

      <div className="px-4">
          <QuestionCard 
            question={currentQ}
            mode={mode}
            onAnswer={handleAnswer}
            showFeedback={mode !== AppMode.MOCK_TEST}
            userAnswer={answers[currentQ.id]}
            onReportRequest={onReportRequest}
          />
      </div>

      {/* Footer Navigation */}
      <div className="flex justify-between items-center px-6 py-8">
        <button 
            onClick={() => setCurrentIndex(p => Math.max(0, p - 1))}
            disabled={currentIndex === 0}
            className="px-6 py-2 rounded-lg bg-gray-100 text-gray-700 font-medium disabled:opacity-50 hover:bg-gray-200 transition-colors"
        >
            Předchozí
        </button>

        {mode === AppMode.TRAINING || mode === AppMode.MISTAKES ? (
             <button 
             onClick={() => {
                 if (currentIndex === currentQuestions.length - 1) {
                     finishTest();
                 } else {
                    setCurrentIndex(p => p + 1);
                 }
             }}
             className="px-6 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
         >
             {currentIndex === currentQuestions.length - 1 ? 'Ukončit trénink' : 'Další otázka'}
         </button>
        ) : (
            currentIndex === currentQuestions.length - 1 ? (
                <button 
                    onClick={mode === AppMode.REVIEW ? onExit : finishTest}
                    className="px-8 py-2 rounded-lg bg-green-600 text-white font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200"
                >
                    {mode === AppMode.REVIEW ? 'Zpět do menu' : 'Vyhodnotit test'}
                </button>
            ) : (
                <button 
                    onClick={() => setCurrentIndex(p => Math.min(currentQuestions.length - 1, p + 1))}
                    className="px-6 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
                >
                    Další
                </button>
            )
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../firebaseConfig';
import { doc, setDoc, getDoc, collection, query, where, getDocs, updateDoc, serverTimestamp, deleteDoc, onSnapshot } from 'firebase/firestore';
import { Subject, BattleRoom, AppMode } from '../types';
import { AppUser } from '../users';
import { BattleArena } from './BattleArena';
import { QUESTIONS_SPS_FOR_TESTS } from '../constants';

interface Props {
  currentUser: AppUser;
  subject: Subject;
  stats: any;
  onExit: () => void;
}

export const BattleManager: React.FC<Props> = ({ currentUser, subject, stats, onExit }) => {
  const [view, setView] = useState<'JOIN' | 'LOBBY' | 'ARENA'>('JOIN');
  const [roomCode, setRoomCode] = useState('');
  const [currentRoom, setCurrentRoom] = useState<BattleRoom | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (view === 'LOBBY' && currentRoom) {
      const unsub = onSnapshot(doc(db, "battles", currentRoom.id), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data() as BattleRoom;
          if (data.status === 'STARTING' || data.status === 'IN_PROGRESS') {
            setCurrentRoom(data);
            setView('ARENA');
          }
        }
      });
      return () => unsub();
    }
  }, [view, currentRoom]);

  const canCreate = () => {
    const today = new Date().toISOString().split('T')[0];
    if (stats?.lastBattleDate === today && (stats?.battlesPlayedToday || 0) >= 2) {
      return false;
    }
    return true;
  };

  const createRoom = async () => {
    if (!canCreate()) {
      setError("Dnes jsi už vytvořil 2 hry. Můžeš se už jen připojit ke kódům od kamarádů (to je neomezené)!");
      return;
    }

    setLoading(true);
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    const roomId = `room_${Date.now()}`;

    // POUŽÍVÁME FILTROVANÝ SEZNAM OTÁZEK
    const shuffled = [...QUESTIONS_SPS_FOR_TESTS].sort(() => 0.5 - Math.random()).slice(0, 20);
    const questionIds = shuffled.map(q => q.id);

    const newRoom: BattleRoom = {
      id: roomId,
      code,
      subject,
      status: 'WAITING',
      questions: questionIds,
      players: {
        [currentUser.uid]: {
          uid: currentUser.uid,
          displayName: currentUser.displayName,
          progress: 0,
          score: 0,
          finished: false,
          ready: true
        }
      },
      createdAt: serverTimestamp()
    };

    try {
      await setDoc(doc(db, "battles", roomId), newRoom);

      const userRef = doc(db, "users", currentUser.uid);
      const today = new Date().toISOString().split('T')[0];
      const newCount = stats?.lastBattleDate === today ? (stats?.battlesPlayedToday || 0) + 1 : 1;

      await setDoc(userRef, { 
        displayName: currentUser.displayName,
        statsSPS: {
          battlesPlayedToday: newCount,
          lastBattleDate: today
        }
      }, { merge: true });

      setCurrentRoom(newRoom);
      setView('LOBBY');
    } catch (e) {
      console.error(e);
      setError("Nepodařilo se vytvořit místnost.");
    } finally {
      setLoading(false);
    }
  };

  const joinRoom = async () => {
    if (!roomCode || roomCode.length !== 6) {
        setError("Zadej platný 6místný kód.");
        return;
    }

    setLoading(true);
    setError('');

    try {
      const q = query(collection(db, "battles"), where("code", "==", roomCode), where("status", "==", "WAITING"));
      const querySnapshot = await getDocs(q);

      if (querySnapshot.empty) {
        setError("Kód neexistuje, místnost je plná nebo hra už začala.");
        setLoading(false);
        return;
      }

      const roomDoc = querySnapshot.docs[0];
      const roomData = roomDoc.data() as BattleRoom;

      const updatedPlayers = {
        ...roomData.players,
        [currentUser.uid]: {
          uid: currentUser.uid,
          displayName: currentUser.displayName,
          progress: 0,
          score: 0,
          finished: false,
          ready: true
        }
      };

      // Nastavíme čas vypršení na 30 minut od TEĎ
      const expiresAt = Date.now() + (30 * 60 * 1000);

      await updateDoc(doc(db, "battles", roomDoc.id), {
        players: updatedPlayers,
        status: 'STARTING',
        expiresAt
      });

      setCurrentRoom({ ...roomData, players: updatedPlayers, status: 'STARTING', expiresAt });
      setView('ARENA');
    } catch (e) {
      setError("Chyba při připojování.");
    } finally {
      setLoading(false);
    }
  };

  if (view === 'ARENA' && currentRoom) {
      return <BattleArena room={currentRoom} currentUser={currentUser} onExit={onExit} stats={stats} />;
  }

  return (
    <div className="max-w-md mx-auto mt-20 p-6 bg-white rounded-2xl shadow-xl border border-gray-100">
      <h2 className="text-2xl font-bold text-center mb-2">1v1 Bitva SPS</h2>
      <p className="text-center text-gray-500 text-sm mb-6">Souboj v reálném čase</p>

      {error && (
        <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-lg text-sm font-medium border border-red-100">
          {error}
        </div>
      )}

      {view === 'JOIN' ? (
        <div className="space-y-6">
          <button 
            onClick={createRoom}
            disabled={loading}
            className="w-full py-4 bg-blue-600 text-white font-bold rounded-xl shadow-lg hover:bg-blue-700 transition-all flex flex-col items-center justify-center"
          >
            <span>{loading ? "Vytvářím..." : "Vytvořit hru"}</span>
            {!loading && <span className="text-[10px] opacity-70 font-normal">Tato akce stojí 1 ze 2 denních pokusů</span>}
          </button>

          <div className="relative flex items-center py-2">
            <div className="flex-grow border-t border-gray-200"></div>
            <span className="flex-shrink mx-4 text-gray-400 text-sm italic">nebo se připoj</span>
            <div className="flex-grow border-t border-gray-200"></div>
          </div>

          <div className="space-y-3">
            <p className="text-xs font-bold text-gray-400 uppercase text-center">Připojení ke kódu je ZDARMA</p>
            <input 
              type="text" 
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.replace(/\D/g,'').slice(0,6))}
              placeholder="000000"
              className="w-full p-4 border-2 border-gray-200 rounded-xl text-center text-3xl font-black tracking-[0.5em] focus:border-blue-500 outline-none transition-all"
            />
            <button 
              onClick={joinRoom}
              disabled={loading || roomCode.length !== 6}
              className="w-full py-4 bg-gray-900 text-white font-bold rounded-xl hover:bg-black disabled:opacity-50 transition-all shadow-md"
            >
              Vstoupit do boje
            </button>
          </div>

          <button onClick={onExit} className="w-full py-2 text-gray-400 text-sm hover:text-gray-600 transition-colors">
            Zpět do menu
          </button>
        </div>
      ) : (
        <div className="text-center space-y-6 animate-in fade-in duration-500">
          <div className="p-8 bg-blue-50 rounded-3xl border-2 border-dashed border-blue-200">
            <p className="text-blue-600 font-bold mb-2 uppercase text-xs tracking-widest">Tvůj kód bitvy</p>
            <h3 className="text-6xl font-black tracking-tighter text-blue-900">{currentRoom?.code}</h3>
          </div>
          <div className="space-y-2">
            <p className="text-gray-500 font-medium">Pošli kód soupeři...</p>
            <div className="flex justify-center gap-1">
                <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce delay-150"></div>
            </div>
          </div>
          <button 
            onClick={async () => {
                if (currentRoom) await deleteDoc(doc(db, "battles", currentRoom.id));
                setView('JOIN');
            }} 
            className="px-4 py-2 text-red-500 font-bold text-sm hover:bg-red-50 rounded-lg transition-all"
          >
            Zrušit místnost
          </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Question } from '../types';
import { QuestionCard } from './QuestionCard';
import { AppMode } from '../types';
import { db, auth } from '../firebaseConfig';
import { doc, getDoc, setDoc } from 'firebase/firestore';

interface Props {
  initialQuestions: Question[];
  onExit: () => void;
  currentUser: any;
}

export const SuddenDeathGame: React.FC<Props> = ({ initialQuestions, onExit, currentUser }) => {
  const [currentQuestion, setCurrentQuestion] = useState<Question | null>(null);
  const [streak, setStreak] = useState(0);
  const [timeLeft, setTimeLeft] = useState(20); // Změna na 20s
  const [gameOver, setGameOver] = useState(false);
  const [usedQuestionIds, setUsedQuestionIds] = useState<Set<number>>(new Set());
  const [bestStreak, setBestStreak] = useState(0);

  // added comment above fix: Use 'any' instead of 'NodeJS.Timeout' to avoid namespace errors.
  const timerRef = useRef<any>(null);

  // Načtení nejlepšího streaku při startu
  useEffect(() => {
    const loadBestStreak = async () => {
      if (currentUser && db) {
        const userRef = doc(db, "users", currentUser.uid);
        const snap = await getDoc(userRef);
        if (snap.exists()) {
          setBestStreak(snap.data().statsSPS?.bestStreak || 0);
        }
      }
    };
    loadBestStreak();
    nextQuestion();
    return () => stopTimer();
  }, []);

  const stopTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const startTimer = () => {
    stopTimer();
    setTimeLeft(20); // Změna na 20s
    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          handleGameOver();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const nextQuestion = () => {
    // Vybrat náhodnou otázku, která ještě nebyla (A NENÍ TO Q254)
    const available = initialQuestions.filter(q => !usedQuestionIds.has(q.id) && q.id !== 254);

    if (available.length === 0) {
      // Došly otázky (teoreticky nemožné v tomto módu, ale pro jistotu)
      setUsedQuestionIds(new Set()); // Reset
      const pool = initialQuestions.filter(q => q.id !== 254);
      const random = pool[Math.floor(Math.random() * pool.length)];
      setCurrentQuestion(random);
    } else {
      const random = available[Math.floor(Math.random() * available.length)];
      setCurrentQuestion(random);
      setUsedQuestionIds(prev => new Set(prev).add(random.id));
    }

    startTimer();
  };

  const handleGameOver = async () => {
    stopTimer();
    setGameOver(true);

    // Uložení nového rekordu
    if (streak > bestStreak && currentUser) {
      setBestStreak(streak);
      try {
        const userRef = doc(db, "users", currentUser.uid);
        await setDoc(userRef, {
          statsSPS: {
            bestStreak: streak
          }
        }, { merge: true });
      } catch (e) {
        console.error("Failed to save streak", e);
      }
    }
  };

  const handleAnswer = (qId: number, idx: number, isCorrect: boolean) => {
    if (isCorrect) {
      setStreak(s => s + 1);
      nextQuestion();
    } else {
      handleGameOver();
    }
  };

  if (gameOver) {
    return (
      <div className="max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-2xl border-4 border-red-100 text-center animate-in zoom-in duration-300">
        <div className="w-24 h-24 mx-auto mb-6 bg-red-100 rounded-full flex items-center justify-center text-5xl">
          ☠️
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-2">KONEC HRY</h2>
        <p className="text-gray-500 mb-8 font-medium">Jedna chyba a jsi venku...</p>

        <div className="grid grid-cols-2 gap-4 mb-8">
          <div className="p-4 bg-gray-50 rounded-2xl border border-gray-200">
            <p className="text-xs uppercase text-gray-400 font-bold mb-1">Dnešní Streak</p>
            <p className="text-3xl font-black text-blue-600">{streak}</p>
          </div>
          <div className="p-4 bg-yellow-50 rounded-2xl border border-yellow-200">
            <p className="text-xs uppercase text-yellow-600 font-bold mb-1">Tvůj Rekord</p>
            <p className="text-3xl font-black text-yellow-700">{Math.max(streak, bestStreak)}</p>
          </div>
        </div>

        <button 
          onClick={() => {
            setGameOver(false);
            setStreak(0);
            setUsedQuestionIds(new Set());
            nextQuestion();
          }}
          className="w-full py-4 bg-red-600 text-white font-bold rounded-xl hover:bg-red-700 transition-all shadow-lg shadow-red-200 mb-3"
        >
          Zkusit znovu
        </button>
        <button 
          onClick={onExit}
          className="w-full py-3 text-gray-500 font-bold hover:text-gray-800 transition-colors"
        >
          Zpět do menu
        </button>
      </div>
    );
  }

  if (!currentQuestion) return <div className="text-center mt-20">Načítám arénu...</div>;

  return (
    <div className="max-w-4xl mx-auto w-full px-4 pt-6">
      {/* HUD */}
      <div className="flex items-center justify-between mb-6 bg-gray-900 text-white p-4 rounded-2xl shadow-lg">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-bold text-lg border-2 border-red-400">
            {streak}
          </div>
          <div className="flex flex-col">
            <span className="text-xs text-gray-400 uppercase font-bold tracking-wider">Streak</span>
            <span className="font-bold text-red-400">NÁHLÁ SMRT</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <span className="text-xs text-gray-400 font-mono">ČAS:</span>
           <span className={`text-2xl font-mono font-black ${timeLeft <= 5 ? 'text-red-500 animate-pulse' : 'text-white'}`}>
             {timeLeft}s
           </span>
        </div>
      </div>

      {/* Progress bar pro čas (upraveno na 20s) */}
      <div className="w-full h-2 bg-gray-200 rounded-full mb-8 overflow-hidden">
        <div 
          className={`h-full transition-all duration-1000 ease-linear ${timeLeft <= 7 ? 'bg-red-600' : 'bg-blue-600'}`}
          style={{ width: `${(timeLeft / 20) * 100}%` }}
        ></div>
      </div>

      <QuestionCard 
        question={currentQuestion}
        mode={AppMode.MOCK_TEST} // Používáme mock test mód pro vzhled (bez okamžitého vyhodnocení v kartě)
        onAnswer={handleAnswer}
        showFeedback={false}
      />

      <div className="text-center mt-8">
        <button onClick={onExit} className="text-gray-400 hover:text-red-500 text-sm font-medium transition-colors">
          Vzdát to a odejít
        </button>
      </div>
    </div>
  );
};

