                ))}
            </div>
        </div>
      )}

      {subject && mode === AppMode.BATTLE && currentUser && <BattleManager currentUser={currentUser} subject={subject} stats={statsSPS} onExit={() => setMode(AppMode.MENU)} />}
      {subject && mode === AppMode.SUDDEN_DEATH && currentUser && <SuddenDeathGame initialQuestions={currentQuestions} currentUser={currentUser} onExit={() => setMode(AppMode.MENU)} />}
      {subject && (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) && <TestRunner key={subject + mode + selectedCategoryId} mode={mode} mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined} onComplete={handleTestComplete} onExit={() => setMode(AppMode.MENU)} onReportRequest={(id) => setReportingQuestionId(id)} initialQuestionsForMode={currentQuestions} initialQuestions={mode === AppMode.REVIEW ? lastTestQuestions : undefined} initialAnswers={mode === AppMode.REVIEW ? lastUserAnswers : undefined} subject={subject} />}
    </div>
  );
};

